import type {RequestContext} from './context.ts';
export function createContext(value: string, userId: string): RequestContext {return {traceId:value,userId};}
export function forkContext(context: RequestContext, suffix: string): RequestContext {return {...context, traceId: context.traceId+'/'+suffix};}

import type {RequestContext} from './context.ts';
import {auditLabel} from './job-types.ts';
import type {Job} from './job-types.ts';
export function describeJob(job: Job, context: RequestContext) {return {requestId:job.requestId,trace:context.traceId,audit:auditLabel(job.requestId),name:job.name};}

import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {auditLabel} from '../src/job-types.ts';
import {headers} from '../src/middleware.ts';
import {logFields} from '../src/logging.ts';
import {response} from '../src/response.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {plugin0} from '../src/plugins/plugin0.ts';
import {record0} from '../src/catalog/record0.ts';

describe('end-to-end propagation', () => {
  test('trace identifier reaches every stage through handle', () => {
    const trace = 'trace-abc-123';
    const user = 'user-xyz-456';
    const job = {requestId: 'job-999', name: 'process-items'};

    const result = handle(trace, user, job);

    // RequestContext has traceId and no requestId compatibility member
    assert.equal(result.context.traceId, trace);
    assert.equal(result.context.userId, user);
    assert.equal('requestId' in result.context, false);

    // Middleware headers preserve output format with traceId value
    assert.deepEqual(result.headers, {'x-request-id': trace});

    // Logging preserves wire/output key requestId with traceId value
    assert.deepEqual(result.logs, {requestId: trace, userId: user});

    // Body preserves wire/output key requestId
    assert.equal(result.body.requestId, trace);

    // Worker payload has propagated trace identifier with forkContext suffix
    assert.equal(result.body.payload.trace, `${trace}/worker`);
  });

  test('context non-mutation behavior and forkContext suffixes', () => {
    const root = createContext('root-trace', 'alice');
    assert.equal(root.traceId, 'root-trace');
    assert.equal(root.userId, 'alice');
    assert.equal('requestId' in root, false);

    const child = forkContext(root, 'worker');
    assert.equal(child.traceId, 'root-trace/worker');
    assert.equal(child.userId, 'alice');

    // Root context must not be mutated
    assert.equal(root.traceId, 'root-trace');

    const grandChild = forkContext(child, 'step1');
    assert.equal(grandChild.traceId, 'root-trace/worker/step1');
    assert.equal(child.traceId, 'root-trace/worker');
  });

  test('traceSummary preserves plugin consumers and traceId propagation', () => {
    const ctx = createContext('summary-trace-001', 'bob');
    const summary = traceSummary(ctx);

    assert.equal(summary.length, 8);
    for (let i = 0; i < 8; i++) {
      assert.equal(summary[i].requestId, 'summary-trace-001');
      assert.equal(summary[i].tag, `plugin${i}`);
      assert.equal(summary[i].user, 'bob');
    }

    assert.deepEqual(plugin0(ctx), {
      requestId: 'summary-trace-001',
      tag: 'plugin0',
      user: 'bob',
    });
  });

  test('headers, logFields, and response preserve signatures and output keys', () => {
    const ctx = createContext('test-trace', 'user-test');
    assert.deepEqual(headers(ctx), {'x-request-id': 'test-trace'});
    assert.deepEqual(logFields(ctx), {requestId: 'test-trace', userId: 'user-test'});
    assert.deepEqual(response(ctx, {data: 123}), {requestId: 'test-trace', payload: {data: 123}});
  });
});

describe('unrelated Job identifier', () => {
  test('Job.requestId and audit are distinct from context traceId', () => {
    const job = {requestId: 'job-id-555', name: 'sync-db'};
    const ctx = createContext('trace-id-777', 'admin');

    const jobDescription = describeJob(job, ctx);

    assert.equal(jobDescription.requestId, 'job-id-555');
    assert.equal(jobDescription.trace, 'trace-id-777');
    assert.equal(jobDescription.audit, 'job:job-id-555');
    assert.equal(jobDescription.name, 'sync-db');
    assert.equal(auditLabel('job-id-555'), 'job:job-id-555');
  });

  test('handle preserves Job.requestId alongside distinct traceId', () => {
    const job = {requestId: 'job-independent', name: 'export'};
    const result = handle('trace-independent', 'user-1', job);

    assert.equal(result.context.traceId, 'trace-independent');
    assert.equal(result.body.payload.requestId, 'job-independent');
    assert.equal(result.body.payload.trace, 'trace-independent/worker');
    assert.equal(result.body.payload.audit, 'job:job-independent');
  });

  test('catalog RequestContext and requestId are preserved', () => {
    const catalogCtx = {requestId: 'catalog-item-1', category: 'electronics'};
    const result = record0(catalogCtx);
    assert.equal(result.requestId, 'catalog-item-1');
    assert.equal(result.category, 'electronics');
    assert.equal(result.label, 'record0:catalog-item-1');
  });
});

